import java.util.*;import java.time.*;
abstract class Subscription {String name;LocalDate startDate;Subscription(String n,LocalDate d){name=n;startDate=d;}abstract int getValidityDays();LocalDate calculateRenewalDate(){return startDate.plusDays(getValidityDays());}}
class Basic extends Subscription {Basic(String n,LocalDate d){super(n,d);}int getValidityDays(){return 30;}}
class Standard extends Subscription {Standard(String n,LocalDate d){super(n,d);}int getValidityDays(){return 90;}}
class Premium extends Subscription {Premium(String n,LocalDate d){super(n,d);}int getValidityDays(){return 365;}}
public class StreamingPlanRenewalReminder {public static void main(String[] args){Scanner sc=new Scanner(System.in);int n=sc.nextInt();for(int i=0;i<n;i++){String type=sc.next(),name=sc.next();LocalDate date=LocalDate.parse(sc.next());Subscription s;switch(type){case "BASIC":s=new Basic(name,date);break;case "STANDARD":s=new Standard(name,date);break;default:s=new Premium(name,date);}System.out.println(s.name+": "+s.calculateRenewalDate());}sc.close();}}